<script setup lang="ts">
import IpPolicySummary from "../components/IpPolicySummary.vue";
import PlanIpAllowance from "../components/PlanIpAllowance.vue";
import CustomerCheckoutModal from "../components/CustomerCheckoutModal.vue";
import CustomerRenewalEligibility from "../components/CustomerRenewalEligibility.vue";
import CustomerLoyalty from "../components/CustomerLoyalty.vue";
import TrialOffer from "../components/trials/TrialOffer.vue";
import { ref, onMounted, onUnmounted, watch } from "vue";
import { useI18n } from "vue-i18n";
import { useRouter, useRoute } from "vue-router";
import { useCustomerAuth } from "@papilio/auth";
import { ApiError, request, item, query, type CheckoutIntent, type CustomerPriceQuote, type Page, type Topup, type Plan, type PaymentDestination, type AccountPreferences, type Subscription, type AccountDelivery, type WalletEntry } from "@papilio/api";
import NumField from "@papilio/ui/NumField.vue";
import { toman, faNumber, faDate, asciiDigits } from "@papilio/ui";
import TopupEvidence from "../components/TopupEvidence.vue";
const { t } = useI18n();
const auth=useCustomerAuth(); const router=useRouter();const route=useRoute();let linkedVersion=0; const tab=ref<"wallet"|"plans"|"subscriptions"|"ledger">("wallet"); const error=ref(""); const notice=ref(""); const busy=ref(false); const preferences=ref<AccountPreferences|null>(null); const balance=ref<number|null>(null); const amount=ref(""); const topupKey=ref(crypto.randomUUID()); const purchaseKey=ref(crypto.randomUUID());
const checkoutOpen=ref(false),checkoutId=ref<number|null>(null);const checkoutFilter=ref<CheckoutIntent["state"]|"">("");const checkouts=ref<CheckoutIntent[]>([]),checkoutPage=ref(1),checkoutPages=ref(1),checkoutState=ref<"idle"|"loading"|"ready"|"error">("idle");let checkoutVersion=0;
const topups=ref<Topup[]>([]);const topupPage=ref(1);const topupPages=ref(1);const topupState=ref<"loading"|"ready"|"error">("loading");const selectedTopup=ref<Topup|null>(null);
const destinations=ref<PaymentDestination[]>([]);const destinationPage=ref(1);const destinationPages=ref(1);const destinationQ=ref("");const destinationState=ref<"idle"|"loading"|"ready"|"error">("idle");const selectedDestination=ref<PaymentDestination|null>(null);
const plans=ref<Plan[]>([]);const planPage=ref(1);const planPages=ref(1);const planQ=ref("");const planState=ref<"idle"|"loading"|"ready"|"error">("idle");const selectedPlan=ref<Plan|null>(null);const selectedQuote=ref<CustomerPriceQuote|null>(null);const quoteBusy=ref(false);let quoteVersion=0;const autoRenew=ref(false);
const subscriptions=ref<Subscription[]>([]);const subscriptionPage=ref(1);const subscriptionPages=ref(1);const subscriptionState=ref<"idle"|"loading"|"ready"|"error">("idle");const selectedSubscription=ref<Subscription|null>(null);const delivery=ref<AccountDelivery|null>(null);
const ledger=ref<WalletEntry[]>([]);const ledgerPage=ref(1);const ledgerPages=ref(1);const ledgerState=ref<"idle"|"loading"|"ready"|"error">("idle");
let walletVersion=0,destinationVersion=0,planVersion=0,subscriptionVersion=0,ledgerVersion=0,deliveryVersion=0;let alive=true;
function fail(cause:unknown):void {error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";}
async function loadWallet():Promise<void> {const stamp=++walletVersion;topupState.value="loading";try {const [wallet,prefs,rows]=await Promise.all([item<{balance_rial:number}>("/v1/customer/wallet"),item<AccountPreferences>("/v1/customer/preferences"),request<Page<Topup>>(`/v1/customer/topups?${query({page:topupPage.value})}`)]);if(!alive||stamp!==walletVersion)return;balance.value=wallet.balance_rial;preferences.value=prefs;topups.value=rows.data;topupPages.value=rows.meta.pager?.total_pages??1;topupState.value="ready";if(selectedTopup.value){ const id=selectedTopup.value.id;const fresh=await item<Topup>(`/v1/customer/topups/${id}`);if(alive&&stamp===walletVersion&&selectedTopup.value?.id===id)selectedTopup.value=fresh;}}catch(cause){if(stamp===walletVersion){topupState.value="error";fail(cause);}}}
async function loadDestinations():Promise<void> {const stamp=++destinationVersion;destinationState.value="loading";try{const rows=await request<Page<PaymentDestination>>(`/v1/customer/payment-destinations?${query({page:destinationPage.value,q:destinationQ.value})}`);if(!alive||stamp!==destinationVersion)return;destinations.value=rows.data;destinationPages.value=rows.meta.pager?.total_pages??1;destinationState.value="ready";}catch(cause){if(stamp===destinationVersion){destinationState.value="error";fail(cause);}}}
async function loadPlans():Promise<void>{const stamp=++planVersion;planState.value="loading";try{const rows=await request<Page<Plan>>(`/v1/customer/plans?${query({page:planPage.value,q:planQ.value})}`);if(!alive||stamp!==planVersion)return;plans.value=rows.data;planPages.value=rows.meta.pager?.total_pages??1;planState.value="ready";}catch(cause){if(stamp===planVersion){planState.value="error";fail(cause);}}}
async function loadSubscriptions():Promise<void>{const stamp=++subscriptionVersion;subscriptionState.value="loading";try{const rows=await request<Page<Subscription>>(`/v1/customer/subscriptions?${query({page:subscriptionPage.value})}`);if(!alive||stamp!==subscriptionVersion)return;subscriptions.value=rows.data;subscriptionPages.value=rows.meta.pager?.total_pages??1;subscriptionState.value="ready";}catch(cause){if(stamp===subscriptionVersion){subscriptionState.value="error";fail(cause);}}}
async function loadCheckouts():Promise<void>{const stamp=++checkoutVersion;checkoutState.value="loading";try{const result=await request<Page<CheckoutIntent>>(`/v1/customer/checkouts?${query({page:checkoutPage.value,state:checkoutFilter.value||undefined})}`);if(!alive||stamp!==checkoutVersion)return;checkouts.value=result.data;checkoutPages.value=result.meta.pager?.total_pages??1;checkoutState.value="ready";}catch(cause){if(alive&&stamp===checkoutVersion){checkoutState.value="error";fail(cause);}}}
function beginCheckout():void{if(!selectedPlan.value)return;checkoutId.value=null;checkoutOpen.value=true;}
function resumeCheckout(row:CheckoutIntent):void{checkoutId.value=row.id;checkoutOpen.value=true;}
function checkoutSaved(row:CheckoutIntent):void{checkoutId.value=row.id;void router.replace({query:{...route.query,checkout_id:String(row.id)}});void loadCheckouts();void loadWallet();}
async function loadLedger():Promise<void>{const stamp=++ledgerVersion;ledgerState.value="loading";try{const rows=await request<Page<WalletEntry>>(`/v1/customer/wallet/entries?${query({page:ledgerPage.value})}`);if(!alive||stamp!==ledgerVersion)return;ledger.value=rows.data;ledgerPages.value=rows.meta.pager?.total_pages??1;ledgerState.value="ready";}catch(cause){if(stamp===ledgerVersion){ledgerState.value="error";fail(cause);}}}
function switchTab(value:typeof tab.value):void{tab.value=value;error.value="";if(value==="wallet")void loadWallet();else if(value==="plans"){void loadPlans();void loadCheckouts();}else if(value==="subscriptions")void loadSubscriptions();else void loadLedger();}
async function topup():Promise<void>{busy.value=true;error.value="";notice.value="";try{const normalized=asciiDigits(amount.value).replace(/٫/g,".");if(!/^\d+(?:\.\d)?$/.test(normalized))throw new Error(t("customerPortal.amountPrecisionError"));const rial=Math.round(Number(normalized)*10);if(!Number.isSafeInteger(rial)||rial<=0)throw new Error(t("customerPortal.amountInvalidError"));selectedTopup.value=await item<Topup>("/v1/customer/topups","POST",{request_key:topupKey.value,amount_rial:rial,destination_id:preferences.value?.checkout.destination_mode==="legacy"?null:selectedDestination.value?.destination_id??null});topupKey.value=crypto.randomUUID();notice.value=t("customerPortal.topupRequested");await loadWallet();}catch(cause){fail(cause);}finally{busy.value=false;}}
async function choosePlan(row:Plan):Promise<void>{if(busy.value)return;selectedPlan.value=row;selectedQuote.value=null;purchaseKey.value=crypto.randomUUID();notice.value="";await loadQuote(row.id);}
async function loadQuote(id:number):Promise<void>{const stamp=++quoteVersion;quoteBusy.value=true;selectedQuote.value=null;error.value="";try{const result=await item<CustomerPriceQuote>(`/v1/customer/plans/${id}/quote`);if(alive&&stamp===quoteVersion&&selectedPlan.value?.id===id)selectedQuote.value=result;}catch(cause){if(alive&&stamp===quoteVersion)fail(cause);}finally{if(stamp===quoteVersion)quoteBusy.value=false;}}
async function purchase():Promise<void>{if(!selectedPlan.value||!selectedQuote.value||quoteBusy.value)return;busy.value=true;error.value="";notice.value="";try{const result=await item<Subscription>("/v1/customer/subscriptions","POST",{plan_id:selectedPlan.value.id,expected_price_rial:selectedQuote.value.price_rial,auto_renew:autoRenew.value,purchase_key:purchaseKey.value});purchaseKey.value=crypto.randomUUID();selectedSubscription.value=result;notice.value=t("customerPortal.purchaseSubmitted",{id:faNumber(result.id)});tab.value="subscriptions";await Promise.all([loadWallet(),loadSubscriptions()]);await showDelivery(result);}catch(cause){fail(cause);if(cause instanceof ApiError && cause.code==="purchase_price_changed" && selectedPlan.value){selectedQuote.value=null;const id=selectedPlan.value.id;try{const fresh=await item<Plan>(`/v1/customer/plans/${id}`);if(alive&&selectedPlan.value?.id===id){selectedPlan.value=fresh;plans.value=plans.value.map(row=>row.id===id?fresh:row);await loadQuote(id);}}catch{error.value+=" · "+t("errors.request_failed");}}}finally{busy.value=false;}}
async function showDelivery(row:Subscription):Promise<void>{selectedSubscription.value=row;delivery.value=null;const stamp=++deliveryVersion;try{const result=await item<AccountDelivery>(`/v1/customer/subscriptions/${row.id}/delivery`);if(alive&&stamp===deliveryVersion)delivery.value=result;}catch(cause){if(stamp===deliveryVersion)fail(cause);}}
async function renewal():Promise<void>{if(!selectedSubscription.value)return;busy.value=true;error.value="";try{const result=await item<Subscription>(`/v1/customer/subscriptions/${selectedSubscription.value.id}/auto-renew`,"PATCH",{enabled:!selectedSubscription.value.auto_renew});await showDelivery(result);await loadSubscriptions();}catch(cause){fail(cause);}finally{busy.value=false;}}
async function rotate():Promise<void>{if(!selectedSubscription.value)return;busy.value=true;error.value="";try{delivery.value=await item<AccountDelivery>(`/v1/customer/subscriptions/${selectedSubscription.value.id}/rotate-link`,"POST");notice.value=t("customerPortal.previousUrlRevoked");}catch(cause){fail(cause);}finally{busy.value=false;}}
async function logout():Promise<void>{try{await auth.logout();await router.push("/account/sign-in");}catch(cause){fail(cause);}}
const statuses:Record<string,string>={customer_hold:t("customerPortal.statuses.customerHold"),active:t("customerPortal.statuses.active"),pending_provision:t("customerPortal.statuses.pendingProvision"),revoking:t("customerPortal.statuses.revoking"),expired:t("customerPortal.statuses.expired"),exhausted:t("customerPortal.statuses.exhausted"),suspended:t("customerPortal.statuses.suspended"),failed:t("customerPortal.statuses.failed"),cancelled:t("customerPortal.statuses.cancelled")};
const reasons:Record<string,string>={approved_topup:t("customerPortal.reasons.topup"),purchase:t("customerPortal.reasons.purchase"),auto_renewal:t("customerPortal.reasons.renewal"),provision_refund:t("customerPortal.reasons.refund")};
function linkedId(value:unknown):number|undefined{if(typeof value!=="string"||!/^\d+$/.test(value))return undefined;const id=Number(value);return Number.isSafeInteger(id)&&id>0?id:undefined;}
async function openLinkedTopup(id:number,stamp:number):Promise<void>{try{const row=await item<Topup>(`/v1/customer/topups/${id}`);if(!alive||stamp!==linkedVersion)return;selectedTopup.value=row;switchTab("wallet");}catch(cause){if(alive&&stamp===linkedVersion)fail(cause);}}
async function openLinkedSubscription(id:number,stamp:number):Promise<void>{try{const row=await item<Subscription>(`/v1/customer/subscriptions/${id}`);if(!alive||stamp!==linkedVersion)return;switchTab("subscriptions");await showDelivery(row);}catch(cause){if(alive&&stamp===linkedVersion)fail(cause);}}
watch(()=>[route.query.topup_id,route.query.subscription_id,route.query.checkout_id],()=>{const stamp=++linkedVersion;deliveryVersion++;const ownedCheckoutId=linkedId(route.query.checkout_id);if(ownedCheckoutId!==undefined){checkoutId.value=ownedCheckoutId;checkoutOpen.value=true;}else if(checkoutId.value!==null){checkoutOpen.value=false;checkoutId.value=null;}const topupId=linkedId(route.query.topup_id);const subscriptionId=linkedId(route.query.subscription_id);if(topupId!==undefined)void openLinkedTopup(topupId,stamp);else if(subscriptionId!==undefined)void openLinkedSubscription(subscriptionId,stamp);},{immediate:true});
onMounted(()=>void loadWallet());onUnmounted(()=>{alive=false;deliveryVersion++;quoteVersion++;checkoutVersion++;});
</script>
<template><main class="customer-shell"><header class="page-head"><div><p class="eyebrow">{{ preferences?.brand_title || t('customerAccount.title') }}</p><h1>{{ auth.session?.display_name }}</h1><p class="subtitle">{{ t('customerAccount.walletBalance') }}: {{ balance===null ? t('customerAccount.loading') : toman(balance) }}</p></div><button class="btn secondary" @click="logout">{{ t('customerAccount.signOut') }}</button></header><nav class="customer-tabs" :aria-label="t('customerAccount.sections')"><RouterLink class="btn secondary" to="/account/notifications">{{ t('customerAccount.notifications') }}</RouterLink><RouterLink class="btn secondary" to="/account/support">{{ t('customerAccount.support') }}</RouterLink><button v-for="entry in ([['wallet','walletPayments'],['plans','servicePurchase'],['subscriptions','myServices'],['ledger','walletActivity']] as const)" :key="entry[0]" class="btn" :class="{'secondary':tab!==entry[0]}" @click="switchTab(entry[0])">{{ t('customerAccount.' + entry[1]) }}</button></nav><p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message" role="status">{{ notice }}</p>
<section v-if="tab==='wallet'" class="form-grid"><form class="card card-pad form-grid" @submit.prevent="topup"><h2>{{ t('customerAccount.topupTitle') }}</h2><p v-if="preferences?.payment_instructions">{{ preferences.payment_instructions }}</p><p v-if="preferences?.checkout">{{t("customerPortal.allowedAmount")}}: {{ toman(preferences.checkout.minimum_topup_rial) }} to {{ toman(preferences.checkout.maximum_topup_rial) }}</p><NumField v-model="amount" :label="t('customerAccount.topupAmount')" /><p>{{t("customerPortal.paymentExactAmount")}}</p><div class="inline-actions"><button v-for="value in preferences?.topup_options_rial" :key="value" type="button" class="btn small secondary" @click="amount=String(value/10)">{{ toman(value) }}</button></div><section v-if="preferences?.checkout.destination_mode!=='legacy'" class="form-grid"><h3>{{t("customerPortal.chooseDestination")}}</h3><p v-if="selectedDestination">{{t("customerPortal.selected")}}: {{ selectedDestination.title }} · {{ selectedDestination.recipient }}</p><div class="toolbar"><label class="field"><span>{{t("customerPortal.searchDestinations")}}</span><input v-model="destinationQ" @keydown.enter.prevent="destinationPage=1;loadDestinations()" /></label><button type="button" class="btn secondary" @click="destinationPage=1;loadDestinations()">{{t("customerPortal.search")}}</button><button v-if="preferences?.checkout.destination_mode==='optional'" type="button" class="btn secondary" @click="selectedDestination=null">{{t("customerPortal.noDestination")}}</button></div><p v-if="destinationState==='loading'">{{t("customerPortal.loading")}}</p><p v-else-if="destinationState==='ready' && !destinations.length">{{t("customerPortal.noDestinations")}}</p><div class="inline-actions"><button v-for="row in destinations" :key="row.destination_id" type="button" class="btn secondary" :aria-pressed="selectedDestination?.destination_id===row.destination_id" @click="selectedDestination=row">{{ row.title }} · {{ row.bank_name }}</button></div><div v-if="destinationState!=='idle'" class="pager"><button type="button" :disabled="destinationPage<=1" @click="destinationPage--;loadDestinations()">‹</button><span>{{ faNumber(destinationPage) }}</span><button type="button" :disabled="destinationPage>=destinationPages" @click="destinationPage++;loadDestinations()">›</button></div></section><button class="btn" :disabled="busy || !preferences || (preferences.checkout.destination_mode==='required'&&!selectedDestination)">{{t("customerPortal.createTopup")}}</button></form><section class="card card-pad"><h2>{{ t('customerAccount.paymentsTitle') }}</h2><button class="btn secondary" @click="loadWallet">{{t("customerPortal.refreshPayments")}}</button><p v-if="topupState==='loading'">{{t("customerPortal.loading")}}</p><p v-else-if="topupState==='ready' && !topups.length">{{t("customerPortal.noTopups")}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("customerPortal.payment")}}</th><th>{{t("customerPortal.amount")}}</th><th>{{t("customerPortal.status")}}</th></tr></thead><tbody><tr v-for="row in topups" :key="row.id" tabindex="0" :class="{'selected-row':selectedTopup?.id===row.id}" @click="selectedTopup=row" @keydown.enter="selectedTopup=row"><td>{{ faNumber(row.id) }}</td><td class="tabular" dir="ltr">{{Number.isSafeInteger(row.amount_rial)?String(row.amount_rial)+' RIAL':t("customerPortal.exactAmountUnavailable")}}<small v-if="row.payment_identifier_code4!=null"> · Code {{row.payment_identifier_code4}}</small><br/><small>{{toman(row.amount_rial)}}</small></td><td>{{ row.status==='pending'?t("customerPortal.pendingReview"):row.status==='approved'?t("customerPortal.approved"):t("customerPortal.rejected") }}</td></tr></tbody></table></div><div class="pager"><button :disabled="topupPage<=1" @click="topupPage--;loadWallet()">‹</button><span>{{ faNumber(topupPage) }}</span><button :disabled="topupPage>=topupPages" @click="topupPage++;loadWallet()">›</button></div><RouterLink v-if="selectedTopup" class="btn secondary" :to="{path:'/account/support',query:{topup_id:selectedTopup.id}}">{{t("customerPortal.helpPayment")}}</RouterLink><TopupEvidence v-if="selectedTopup" :key="selectedTopup.id" :topup-id="selectedTopup.id" :topup="selectedTopup" audience="customer" :pending="selectedTopup.status==='pending'" :can-upload="preferences?.receipts.enabled ?? false" /></section></section>
<CustomerLoyalty v-if="tab==='plans' && auth.session" :key="auth.session.customer_id" :customer-id="auth.session.customer_id" /><TrialOffer v-if="tab==='plans' && auth.session" :customer-id="auth.session.customer_id" can-claim /><section v-if="tab==='plans'" class="card card-pad form-grid"><h2>{{t("customerPortal.purchaseWallet")}}</h2><div class="toolbar"><label class="field"><span>{{t("customerPortal.findPlan")}}</span><input v-model="planQ" @keydown.enter="planPage=1;loadPlans()" /></label><button class="btn secondary" @click="planPage=1;loadPlans()">{{t("customerPortal.findPlans")}}</button></div><p v-if="planState==='loading'">{{t("customerPortal.loading")}}</p><p v-else-if="planState==='ready' && !plans.length">{{t("customerPortal.noPlans")}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("customerPortal.plan")}}</th><th>{{t("customerPortal.quota")}}</th><th>{{t("customerPortal.duration")}}</th><th>{{t("customerPortal.price")}}</th></tr></thead><tbody><tr v-for="row in plans" :key="row.id" tabindex="0" :class="{'selected-row':selectedPlan?.id===row.id}" @click="choosePlan(row)" @keydown.enter="choosePlan(row)"><td>{{ row.title }}</td><td>{{ (row.quota_bytes === null ? t("customerPortal.unlimited") : faNumber(row.quota_bytes/1024**3)) }} GiB</td><td>{{ row.duration_days === null ? t("customerPortal.noExpiry") : faNumber(row.duration_days) + " " + t("customerPortal.days") }}</td><td>{{ toman(row.price_rial) }}</td></tr></tbody></table></div><div class="pager"><button :disabled="planPage<=1" @click="planPage--;loadPlans()">‹</button><span>{{ faNumber(planPage) }}</span><button :disabled="planPage>=planPages" @click="planPage++;loadPlans()">›</button></div><form v-if="selectedPlan" class="form-grid" @submit.prevent="purchase"><h3>{{t("customerPortal.purchaseTitle",{title:selectedPlan.title})}}</h3><PlanIpAllowance :policy="selectedPlan.effective_ip_policy" :configured="selectedPlan.ip_limit"/><button type="button" class="btn secondary" :disabled="busy" @click="beginCheckout">{{t("customerPortal.automatedCheckout")}}</button><p v-if="quoteBusy">{{t("customerPortal.loadingPrice")}}</p><section v-if="selectedQuote" class="hint-box" :aria-label="t('customerPortal.personalizedPurchaseQuote')"><p>{{t("customerPortal.basePrice")}}: {{toman(selectedQuote.base_price_rial)}}</p><p>{{t("customerPortal.finalDiscount")}}: {{toman(selectedQuote.discount_rial)}}</p><p><strong>{{t("customerPortal.walletCharge")}}: {{toman(selectedQuote.price_rial)}}</strong></p><p>{{t("customerPortal.renewalPrice")}}: {{toman(selectedQuote.renewal_price_rial)}}</p><p v-if="selectedQuote.tier_code">{{t("customerPortal.tier")}}: {{selectedQuote.tier_code}}</p><p v-if="selectedQuote.first_purchase_discount_bps">{{t("customerPortal.firstPurchaseHint")}}</p><p>{{t("customerPortal.deliveryHint")}}</p></section><button v-if="selectedQuote" type="button" class="btn secondary" :disabled="busy || quoteBusy" @click="loadQuote(selectedPlan.id)">{{t("customerPortal.refreshPrice")}}</button><button v-if="!selectedQuote" type="button" class="btn secondary" :disabled="quoteBusy" @click="loadQuote(selectedPlan.id)">{{t("customerPortal.retryQuote")}}</button><label class="check-row"><input v-model="autoRenew" type="checkbox" />{{t("customerPortal.autoRenew")}}</label><button class="btn" :disabled="busy||quoteBusy||!selectedQuote">{{t("customerPortal.confirmPurchase")}}</button></form></section>
<section v-if="tab==='plans'" class="card card-pad form-grid" :aria-label="t('customerPortal.checkoutHistory')"><h2>{{t("customerPortal.checkouts")}}</h2><label class="field"><span>{{t("customerPortal.checkoutStatus")}}</span><select v-model="checkoutFilter" @change="checkoutPage=1;loadCheckouts()"><option value="">{{t("customerPortal.allStatuses")}}</option><option v-for="state in (['awaiting_funding','ready','action_required','purchased','cancelled','expired'] as const)" :key="state" :value="state">{{t("customerPortal.checkoutState." + state)}}</option></select></label><button class="btn secondary" @click="loadCheckouts">{{t("customerPortal.refreshCheckouts")}}</button><p v-if="checkoutState==='loading'">{{t("customerPortal.loadingCheckouts")}}</p><p v-if="checkoutState==='error'">{{t("customerPortal.checkoutLoadError")}}</p><p v-if="checkoutState==='ready'&&!checkouts.length">{{t("customerPortal.noCheckouts")}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("customerPortal.checkout")}}</th><th>{{t("customerPortal.plan")}}</th><th>{{t("customerPortal.price")}}</th><th>{{t("customerPortal.status")}}</th><th>{{t("customerPortal.expires")}}</th><th>{{t("customerPortal.action")}}</th></tr></thead><tbody><tr v-for="row in checkouts" :key="row.id"><td>{{row.id}}</td><td>{{row.plan_id}}</td><td>{{toman(row.price_rial)}}</td><td>{{t("customerPortal.checkoutState." + row.state)}}</td><td>{{faDate(row.expires_at)}}</td><td><button class="btn small secondary" @click="resumeCheckout(row)">{{t("customerPortal.openCheckout")}} #{{row.id}}</button></td></tr></tbody></table></div><div class="pager"><button :disabled="checkoutPage<=1" @click="checkoutPage--;loadCheckouts()">{{t("customerPortal.previous")}}</button><span>{{checkoutPage}}</span><button :disabled="checkoutPage>=checkoutPages" @click="checkoutPage++;loadCheckouts()">{{t("customerPortal.next")}}</button></div></section><CustomerCheckoutModal :open="checkoutOpen" :plan="selectedPlan" :checkout-id="checkoutId" :preferences="preferences" @close="checkoutOpen=false" @saved="checkoutSaved" />
<section v-if="tab==='subscriptions'" class="card card-pad form-grid"><h2>{{t("customerPortal.services")}}</h2><button class="btn secondary" @click="loadSubscriptions">{{t("customerPortal.refreshServices")}}</button><p v-if="subscriptionState==='loading'">{{t("customerPortal.loading")}}</p><p v-else-if="subscriptionState==='ready' && !subscriptions.length">{{t("customerPortal.noServices")}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("customerPortal.service")}}</th><th>{{t("customerPortal.status")}}</th><th>{{t("customerPortal.usage")}}</th><th>{{t("customerPortal.expires")}}</th><th>{{t("customerPortal.renewal")}}</th></tr></thead><tbody><tr v-for="row in subscriptions" :key="row.id" tabindex="0" :class="{'selected-row':selectedSubscription?.id===row.id}" @click="showDelivery(row)" @keydown.enter="showDelivery(row)"><td>{{ faNumber(row.id) }}</td><td>{{ statuses[row.status]??t("customerPortal.needsReview") }}</td><td>{{ faNumber(row.used_bytes/1024**3) }} / {{ (row.quota_bytes === null ? t("customerPortal.unlimited") : faNumber(row.quota_bytes/1024**3)) }} GiB</td><td>{{ faDate(row.expires_at) }}</td><td>{{ row.auto_renew?t("customerPortal.enabled"):t("customerPortal.disabled") }}</td></tr></tbody></table></div><div class="pager"><button :disabled="subscriptionPage<=1" @click="subscriptionPage--;loadSubscriptions()">‹</button><span>{{ faNumber(subscriptionPage) }}</span><button :disabled="subscriptionPage>=subscriptionPages" @click="subscriptionPage++;loadSubscriptions()">›</button></div><section v-if="selectedSubscription" class="form-grid"><h3>{{t("customerPortal.subscription")}} {{ faNumber(selectedSubscription.id) }}</h3><IpPolicySummary :purchased="selectedSubscription.purchased_ip_policy" :effective="selectedSubscription.effective_ip_policy"/><RouterLink class="btn secondary" :to="{path:'/account/support',query:{subscription_id:selectedSubscription.id}}">{{t("customerPortal.helpService")}}</RouterLink><p v-if="selectedSubscription.entitlement_kind==='trial'" class="badge">{{t("customerPortal.trialNoRenewal")}}</p><button v-else class="btn secondary" :disabled="busy" @click="renewal">{{ selectedSubscription.auto_renew?t("customerPortal.disableRenewal"):t("customerPortal.enableRenewal") }}</button><CustomerRenewalEligibility :subscription-id="selectedSubscription.id" :refresh-key="selectedSubscription.auto_renew" /><template v-if="delivery"><p v-if="delivery.status === 'customer_hold'">{{t("customerPortal.serviceSuspended")}}</p><a v-if="delivery.portal_url" class="btn" :href="delivery.portal_url">{{t("customerPortal.downloadConfigs")}}</a><p v-else>{{t("customerPortal.deliveryUnavailable")}}</p><a v-if="delivery.feed_url" :href="delivery.feed_url" class="private-link" dir="ltr">{{ delivery.feed_url }}</a><p v-if="delivery.can_rotate_link">{{t("customerPortal.rotateWarning")}}</p><button v-if="delivery.can_rotate_link" class="btn secondary" :disabled="busy" @click="rotate">{{t("customerPortal.rotateLink")}}</button></template></section></section>
<section v-if="tab==='ledger'" class="card card-pad form-grid"><h2>{{t("customerPortal.walletActivity")}}</h2><button class="btn secondary" @click="loadLedger">{{t("customerPortal.refreshActivity")}}</button><p v-if="ledgerState==='loading'">{{t("customerPortal.loading")}}</p><p v-else-if="ledgerState==='ready' && !ledger.length">{{t("customerPortal.noActivity")}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("customerPortal.date")}}</th><th>{{t("customerPortal.description")}}</th><th>{{t("customerPortal.amount")}}</th><th>{{t("customerPortal.balance")}}</th></tr></thead><tbody><tr v-for="row in ledger" :key="row.id"><td>{{ faDate(row.created_at) }}</td><td>{{ reasons[row.reason]??t("customerPortal.walletAdjustment") }}</td><td>{{ toman(row.amount_rial) }}</td><td>{{ toman(row.balance_after_rial) }}</td></tr></tbody></table></div><div class="pager"><button :disabled="ledgerPage<=1" @click="ledgerPage--;loadLedger()">‹</button><span>{{ faNumber(ledgerPage) }}</span><button :disabled="ledgerPage>=ledgerPages" @click="ledgerPage++;loadLedger()">›</button></div></section><p v-if="preferences?.support_handle">{{t("customerPortal.support")}}: {{ preferences.support_handle }}</p></main></template>
<style scoped>.customer-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}.private-link{overflow-wrap:anywhere}.form-grid{min-width:0}</style>
